      for (const key in passthrough) {
        this.shader.setUniform(key, passthrough[key])
      }
      this.target.plane(this.target.width, this.target.height)
      this.target.pop()
      return
    }

    this.target.push()
    // Horizontal pass: fbo -> fboA
    this.applyPass(this.fbo, this.fboA, 0)
