const src = fs.readFileSync(
  path.join(
    'D:',
    'gsb-auto',
    'batches',
    'pointwise-20261111-claude-uid831-867',
    '023-p5-filterrenderer',
    'A',
    'GaussianBlurRenderer.js',
  ),
  'utf8',
)

function makeGL({ webgl2, extensions, framebufferComplete = true }) {
  const calls = []
  const ext = {}
  for (const name of extensions) ext[name] = {}
  return {
    calls,
    TEXTURE_2D: 0x0de1,
    TEXTURE_MIN_FILTER: 0x2801,
    TEXTURE_MAG_FILTER: 0x2800,
    TEXTURE_WRAP_S: 0x2802,
    TEXTURE_WRAP_T: 0x2803,
    NEAREST: 0x2600,
    CLAMP_TO_EDGE: 0x812f,
    RGBA: 0x1908,
    RGBA32F: 0x8814,
    FLOAT: 0x1406,
    UNSIGNED_BYTE: 0x1401,
    FRAMEBUFFER: 0x8d40,
    COLOR_ATTACHMENT0: 0x8ce0,
    FRAMEBUFFER_COMPLETE: 0x8cd5,
    FRAMEBUFFER_BINDING: 0x8ca6,
    getExtension(name) {
      calls.push(['getExtension', name])
      return ext[name] || null
    },
    createTexture() {
      const t = { id: 'tex' + calls.length }
      calls.push(['createTexture'])
      return t
    },
    deleteTexture(t) {
      calls.push(['deleteTexture', t])
    },
    createFramebuffer() {
      const f = { id: 'fbo' + calls.length }
      calls.push(['createFramebuffer'])
      return f
    },
    deleteFramebuffer(f) {
      calls.push(['deleteFramebuffer', f])
    },
    bindTexture() {},
    texParameteri() {},
    texImage2D() {},
    bindFramebuffer(target, fb) {
      calls.push(['bindFramebuffer', fb && fb.id])
    },
    framebufferTexture2D() {},
    getParameter(p) {
      if (p === 0x8ca6) return { id: 'prev-binding' }
      return null
    },
    checkFramebufferStatus() {
      calls.push(['checkFramebufferStatus'])
      return framebufferComplete ? 0x8cd5 : 0
    },
  }
}

function makeTarget(gl, webgl2) {
  const log = []
  const makeFbo = (opts) => ({
    opts,
    width: 400,
    height: 400,
    density: 2,
    color: { tag: 'color-of-' + Math.round(log.length * 1000) },
    draw(cb) {
      log.push(['fbo.draw', this.opts.format === 0x1406 ? 'FLOAT' : 'BYTE'])
      cb()
    },
    remove() {
      log.push(['fbo.remove'])
    },
  })
  const target = {
    width: 400,
    height: 400,
    webglVersion: webgl2 ? 2 : 1,
    FLOAT: 0x1406,
    UNSIGNED_BYTE: 0x1401,
    NEAREST: 0x2600,
    _renderer: { GL: gl },
    log,
    framebuffers: [],
    createFramebuffer(opts) {
      return makeFbo(opts || {})
    },
    createShader() {
      const uniforms = {}
      return {
        uniforms,
        setUniform(k, v) {
          uniforms[k] = v
        },
      }
    },
    push() {
      log.push(['push'])
    },
    pop() {
      log.push(['pop'])
    },
    clear() {
      log.push(['clear'])
    },
    noStroke() {},
    shader(s) {
      log.push(['shader'])
      target._currentShader = s
    },
    plane() {
      log.push(['plane'])
    },
    image(fb) {
      log.push(['image', fb])
    },
    resetShader() {
      log.push(['resetShader'])
      target._currentShader = null
    },
    pixelDensity() {
      return 2
    },
  }
  return target
}

class FakeRenderer {
  constructor(target, options) {
    this.target = target
    this.fbo = target.createFramebuffer(options)
    this.shader = target.createShader()
  }
  vert() {
    return 'vert'
  }
  frag() {
    return 'frag'
  }
  remove() {
    this.fbo.remove()
  }
}

