  Renderer: FakeRenderer,
  p5: { prototype: {} },
  WEBGL2: 2,
  console,
  Number,
  Math,
}
vm.createContext(ctx)
vm.runInContext(src, ctx)
const G = ctx.GaussianBlurRenderer

let failures = 0
function check(name, cond, detail) {
  if (cond) {
    console.log('PASS', name)
  } else {
    failures++
    console.log('FAIL', name, detail || '')
  }
}
function approx(a, b, eps = 1e-9) {
  return Math.abs(a - b) < eps
}

// ---- 1. Kernel generation & normalization --------------------------------
{
  const gl = makeGL({ webgl2: true, extensions: ['EXT_color_buffer_float', 'EXT_float_blend'] })
  const t = makeTarget(gl, true)
  const r = new G(t, { radius: 5, sigma: 2 })
  check('kernel length is 2r+1', r.kernel.weights.length === 11, r.kernel.weights.length)
  const sum = r.kernel.weights.reduce((a, b) => a + b, 0)
  check('weights normalize to 1', approx(sum, 1), sum)
  check('offsets span -r..r', r.kernel.offsets[0] === -5 && r.kernel.offsets[10] === 5)
  check('weights symmetric', approx(r.kernel.weights[0], r.kernel.weights[10]))
  check('peak weight at center', r.kernel.weights[5] === Math.max(...r.kernel.weights))
  const u = r.getUniforms(t.fbo.color, 0)
  check('texel size accounts for density', approx(u.uTexelSize[0], 1 / 800), u.uTexelSize)
  check('uKernelSize matches', u.uKernelSize === 11)
}

// ---- 2. Radius cap & invalid radius --------------------------------------
{
  const gl = makeGL({ webgl2: true, extensions: ['EXT_color_buffer_float', 'EXT_float_blend'] })
  const t = makeTarget(gl, true)
  const r = new G(t, { radius: 200, sigma: 3 })
  check('radius hard-capped at 64', r.radius === 64, r.radius)
  check('capped kernel length 129', r.kernel.weights.length === 129)
  r.setRadius(-8)
  check('negative radius -> 0', r.radius === 0)
  check('zero radius identity kernel', r.kernel.offsets.length === 1 && r.kernel.weights[0] === 1)
  r.setRadius(NaN)
  check('NaN radius -> 0', r.radius === 0)
}

// ---- 3. Sigma fallbacks ---------------------------------------------------
{
  const gl = makeGL({ webgl2: true, extensions: ['EXT_color_buffer_float', 'EXT_float_blend'] })
  const t = makeTarget(gl, true)
  const r = new G(t, { radius: 9, sigma: 0 })
  check('sigma 0 falls back to radius/3', approx(r.sigma, 3), r.sigma)
  const r2 = new G(t, { radius: 0, sigma: 0 })
  check('sigma fallback has MIN_SIGMA floor', r2.sigma >= 0.5, r2.sigma)
  const r3 = new G(t, { radius: 10, sigma: -4 })
  check('negative sigma falls back', approx(r3.sigma, 10 / 3), r3.sigma)
  const r4 = new G(t, { radius: 10, sigma: 0.1 })
  check('sub-minimum sigma clamped to MIN_SIGMA', approx(r4.sigma, 0.5), r4.sigma)
  const r5 = new G(t, { radius: 10, sigma: 7 })
  r5.setRadius(4)
  check('explicit sigma preserved across setRadius', approx(r5.sigma, 7))
  const r6 = new G(t, { radius: 12 })
  check('omitted sigma derives from radius', approx(r6.sigma, 4))
  r6.setRadius(3)
