  const t = makeTarget(gl, true)
  const r = new G(t, { radius: 0 })
  t.log.length = 0
  r.draw(() => t.log.push(['scene-cb']))
  const fboDraws = t.log.filter(([k]) => k === 'fbo.draw').length
  check('passthrough: only source fbo draw, zero intermediate passes', fboDraws === 1, JSON.stringify(t.log))
