  check('resetShader happens before image', order.indexOf('resetShader') < order.indexOf('image'))
  check('horizontal then vertical directions', r.shader.uniforms.uDirection === 1)
}

// ---- 6. Float detection: WebGL2 happy path --------------------------------
{
