  const r = new G(t, { radius: 2 })
  check('WebGL2 with extensions -> FLOAT', r.intermediateFormat === t.FLOAT)
  check('probe framebuffer cleaned up', gl.calls.some(([k]) => k === 'deleteFramebuffer'))
