const fs = require('fs')
const path = require('path')
const vm = require('vm')

const src = fs.readFileSync(
  path.join(__dirname, 'GaussianBlurRenderer.js'),
  'utf8',
)

function makeGL({ webgl2, extensions, framebufferComplete = true }) {
  const calls = []
  const ext = {}
  for (const name of extensions) ext[name] = {}
  return {
    calls,
    TEXTURE_2D: 0x0de1,
    TEXTURE_MIN_FILTER: 0x2801,
    TEXTURE_MAG_FILTER: 0x2800,
    TEXTURE_WRAP_S: 0x2802,
    TEXTURE_WRAP_T: 0x2803,
    NEAREST: 0x2600,
    CLAMP_TO_EDGE: 0x812f,
    RGBA: 0x1908,
    RGBA32F: 0x8814,
    FLOAT: 0x1406,
    UNSIGNED_BYTE: 0x1401,
    FRAMEBUFFER: 0x8d40,
    COLOR_ATTACHMENT0: 0x8ce0,
    FRAMEBUFFER_COMPLETE: 0x8cd5,
    FRAMEBUFFER_BINDING: 0x8ca6,
    getExtension(name) {
      calls.push(['getExtension', name])
      return ext[name] || null
    },
    createTexture() {
      const t = { id: 'tex' + calls.length }
      calls.push(['createTexture'])
      return t
    },
    deleteTexture(t) {
      calls.push(['deleteTexture', t])
    },
    createFramebuffer() {
      const f = { id: 'fbo' + calls.length }
      calls.push(['createFramebuffer'])
      return f
    },
    deleteFramebuffer(f) {
      calls.push(['deleteFramebuffer', f])
    },
    bindTexture() {},
    texParameteri() {},
    texImage2D() {},
    bindFramebuffer(target, fb) {
      calls.push(['bindFramebuffer', fb && fb.id])
    },
    framebufferTexture2D() {},
    getParameter(p) {
      if (p === 0x8ca6) return { id: 'prev-binding' }
      return null
    },
    checkFramebufferStatus() {
      calls.push(['checkFramebufferStatus'])
      return framebufferComplete ? 0x8cd5 : 0
    },
  }
}

function makeTarget(gl, webgl2) {
  const log = []
  let fboCounter = 0
  const makeFbo = (opts) => ({
    opts,
    width: 400,
    height: 400,
    density: 2,
    color: { tag: 'color-' + fboCounter++ },
    draw(cb) {
      log.push(['fbo.draw', this.opts.format === 0x1406 ? 'FLOAT' : 'BYTE'])
      cb()
    },
    remove() {
      log.push(['fbo.remove'])
    },
  })
  const target = {
    width: 400,
    height: 400,
    webglVersion: webgl2 ? 2 : 1,
    FLOAT: 0x1406,
    UNSIGNED_BYTE: 0x1401,
    NEAREST: 0x2600,
    _renderer: { GL: gl },
    log,
    createFramebuffer(opts) {
      return makeFbo(opts || {})
    },
    createShader() {
      const uniforms = {}
      return {
        uniforms,
        setUniform(k, v) {
          uniforms[k] = v
        },
      }
    },
    push() {
      log.push(['push'])
    },
    pop() {
      log.push(['pop'])
    },
    clear() {
      log.push(['clear'])
    },
    noStroke() {},
    shader(s) {
      log.push(['shader'])
      target._currentShader = s
    },
    plane() {
      log.push(['plane'])
    },
    image(fb) {
      log.push(['image', fb])
    },
    resetShader() {
      log.push(['resetShader'])
      target._currentShader = null
    },
    pixelDensity() {
      return 2
    },
  }
  return target
}

class FakeRenderer {
  constructor(target, options) {
    this.target = target
    this.fbo = target.createFramebuffer(options)
    this.shader = target.createShader()
  }
  vert() {
    return 'vert'
  }
  frag() {
    return 'frag'
  }
  remove() {
    this.fbo.remove()
  }
}

const ctx = {
  Renderer: FakeRenderer,
  p5: { prototype: {} },
  WEBGL2: 2,
  console,
  Number,
  Math,
}
vm.createContext(ctx)
vm.runInContext(src, ctx)
const G = ctx.GaussianBlurRenderer

let failures = 0
function check(name, cond, detail) {
  if (cond) {
    console.log('PASS', name)
  } else {
    failures++
    console.log('FAIL', name, detail || '')
  }
}
function approx(a, b, eps = 1e-9) {
  return Math.abs(a - b) < eps
}

// ---- 1. Kernel generation & normalization --------------------------------
{
  const gl = makeGL({ webgl2: true, extensions: ['EXT_color_buffer_float', 'EXT_float_blend'] })
  const t = makeTarget(gl, true)
  const r = new G(t, { radius: 5, sigma: 2 })
  check('kernel length is 2r+1', r.kernel.weights.length === 11, r.kernel.weights.length)
  const sum = r.kernel.weights.reduce((a, b) => a + b, 0)
  check('weights normalize to 1', approx(sum, 1), sum)
  check('offsets span -r..r', r.kernel.offsets[0] === -5 && r.kernel.offsets[10] === 5)
  check('weights symmetric', approx(r.kernel.weights[0], r.kernel.weights[10]))
  check('peak weight at center', r.kernel.weights[5] === Math.max(...r.kernel.weights))
  const u = r.getUniforms(t.fbo.color, 0)
  check('texel size accounts for density', approx(u.uTexelSize[0], 1 / 800), u.uTexelSize)
  check('uKernelSize matches', u.uKernelSize === 11)
}

// ---- 2. Radius cap & invalid radius --------------------------------------
{
  const gl = makeGL({ webgl2: true, extensions: ['EXT_color_buffer_float', 'EXT_float_blend'] })
  const t = makeTarget(gl, true)
  const r = new G(t, { radius: 200, sigma: 3 })
  check('radius hard-capped at 64', r.radius === 64, r.radius)
  check('capped kernel length 129', r.kernel.weights.length === 129)
  r.setRadius(-8)
  check('negative radius -> 0', r.radius === 0)
  check('zero radius identity kernel', r.kernel.offsets.length === 1 && r.kernel.weights[0] === 1)
  r.setRadius(NaN)
  check('NaN radius -> 0', r.radius === 0)
}

// ---- 3. Sigma fallbacks ---------------------------------------------------
{
  const gl = makeGL({ webgl2: true, extensions: ['EXT_color_buffer_float', 'EXT_float_blend'] })
  const t = makeTarget(gl, true)
  const r = new G(t, { radius: 9, sigma: 0 })
  check('sigma 0 falls back to radius/3', approx(r.sigma, 3), r.sigma)
  const r2 = new G(t, { radius: 0, sigma: 0 })
  check('sigma fallback has MIN_SIGMA floor', r2.sigma >= 0.5, r2.sigma)
  const r3 = new G(t, { radius: 10, sigma: -4 })
  check('negative sigma falls back', approx(r3.sigma, 10 / 3), r3.sigma)
  const r4 = new G(t, { radius: 10, sigma: 0.1 })
  check('sub-minimum sigma clamped to MIN_SIGMA', approx(r4.sigma, 0.5), r4.sigma)
  const r5 = new G(t, { radius: 10, sigma: 7 })
  r5.setRadius(4)
  check('explicit sigma preserved across setRadius', approx(r5.sigma, 7))
  const r6 = new G(t, { radius: 12 })
  check('omitted sigma derives from radius', approx(r6.sigma, 4))
  r6.setRadius(3)
  check('derived sigma tracks radius when never set explicitly', approx(r6.sigma, 1), r6.sigma)
  const s = r4.kernel.weights.reduce((a, b) => a + b, 0)
  check('weights finite and normalized at MIN_SIGMA', Number.isFinite(s) && approx(s, 1), s)
}

// ---- 4. Zero-radius draw: passthrough, no intermediate draws --------------
{
  const gl = makeGL({ webgl2: true, extensions: ['EXT_color_buffer_float', 'EXT_float_blend'] })
  const t = makeTarget(gl, true)
  const r = new G(t, { radius: 0 })
  t.log.length = 0
  r.draw(() => t.log.push(['scene-cb']))
  const fboDraws = t.log.filter(([k]) => k === 'fbo.draw').length
  check('passthrough: only source fbo draw, zero intermediate passes', fboDraws === 1, JSON.stringify(t.log))
  check('passthrough: one blit plane to canvas', t.log.filter(([k]) => k === 'plane').length === 1)
  check('passthrough: no image() present', !t.log.some(([k]) => k === 'image'))
  check('passthrough kernel uniform is identity', r.shader.uniforms.uKernelSize === 1 && r.shader.uniforms.uWeights[0] === 1)
}

// ---- 5. Blur draw: two passes + image present, resetShader called ---------
{
  const gl = makeGL({ webgl2: true, extensions: ['EXT_color_buffer_float', 'EXT_float_blend'] })
  const t = makeTarget(gl, true)
  const r = new G(t, { radius: 8, sigma: 3 })
  t.log.length = 0
  r.draw(() => t.log.push(['scene-cb']))
  const fboDraws = t.log.filter(([k]) => k === 'fbo.draw')
  check('blur: 3 fbo draws (scene, horizontal, vertical)', fboDraws.length === 3, JSON.stringify(fboDraws))
  check('blur: final present via image()', t.log.some(([k]) => k === 'image'))
  check('blur: resetShader before present', t.log.some(([k]) => k === 'resetShader'))
  const order = t.log.map(([k]) => k)
  check('resetShader happens before image', order.indexOf('resetShader') < order.indexOf('image'))
  check('horizontal then vertical directions', r.shader.uniforms.uDirection === 1)
}

// ---- 6. Float detection: WebGL2 happy path --------------------------------
{
  const gl = makeGL({ webgl2: true, extensions: ['EXT_color_buffer_float', 'EXT_float_blend'] })
  const t = makeTarget(gl, true)
  const r = new G(t, { radius: 2 })
  check('WebGL2 with extensions -> FLOAT', r.intermediateFormat === t.FLOAT)
  check('probe framebuffer cleaned up', gl.calls.some(([k]) => k === 'deleteFramebuffer'))
  check('probe texture cleaned up', gl.calls.some(([k]) => k === 'deleteTexture'))
  check('intermediates created FLOAT', r.fboA.opts.format === t.FLOAT && r.fboB.opts.format === t.FLOAT)
  check('intermediates have no depth', r.fboA.opts.depth === false)
  check('intermediates use NEAREST', r.fboA.opts.textureFiltering === t.NEAREST)
}

// ---- 7. Byte fallback: WebGL2 missing extension ---------------------------
{
  const gl = makeGL({ webgl2: true, extensions: [] })
  const t = makeTarget(gl, true)
  const r = new G(t, { radius: 2 })
  check('WebGL2 missing ext -> UNSIGNED_BYTE', r.intermediateFormat === t.UNSIGNED_BYTE)
  check('format name reports UNSIGNED_BYTE', r.getIntermediateFormatName() === 'UNSIGNED_BYTE')
}

// ---- 8. Byte fallback: WebGL1 missing float ext ---------------------------
{
  const gl = makeGL({ webgl2: false, extensions: [] })
  const t = makeTarget(gl, false)
  const r = new G(t, { radius: 2 })
  check('WebGL1 without OES_texture_float -> BYTE', r.intermediateFormat === t.UNSIGNED_BYTE)
}

