{
  const gl = makeGL({
    webgl2: true,
    extensions: ['EXT_color_buffer_float', 'EXT_float_blend'],
    framebufferComplete: false,
  })
  const t = makeTarget(gl, true)
  const r = new G(t, { radius: 2 })
  check('incomplete float FBO -> BYTE fallback', r.intermediateFormat === t.UNSIGNED_BYTE)
}

