  check('probe framebuffer cleaned up', gl.calls.some(([k]) => k === 'deleteFramebuffer'))
  check('probe texture cleaned up', gl.calls.some(([k]) => k === 'deleteTexture'))
  check('intermediates created FLOAT', r.fboA.opts.format === t.FLOAT && r.fboB.opts.format === t.FLOAT)
  check('intermediates have no depth', r.fboA.opts.depth === false)
  check('intermediates use NEAREST', r.fboA.opts.textureFiltering === t.NEAREST)
}

// ---- 7. Byte fallback: WebGL2 missing extension ---------------------------
{
