  check('format name reports UNSIGNED_BYTE', r.getIntermediateFormatName() === 'UNSIGNED_BYTE')
}

// ---- 8. Byte fallback: WebGL1 missing float ext ---------------------------
{
  const gl = makeGL({ webgl2: false, extensions: [] })
  const t = makeTarget(gl, false)
  const r = new G(t, { radius: 2 })
