const readFbo = (fbo, isFloat) => {
  const gl = drawingContext
  const w = fbo.width * fbo.density
  const h = fbo.height * fbo.density
  // A float color attachment can only be read back as FLOAT; reading a
  // byte attachment with FLOAT is equally invalid, so match the type.
  const pixels = isFloat
    ? new Float32Array(w * h * 4)
    : new Uint8Array(w * h * 4)
  gl.bindFramebuffer(gl.FRAMEBUFFER, fbo.framebuffer)
  gl.readPixels(0, 0, w, h, gl.RGBA, gl.FLOAT, pixels)
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  const channels = [0, 0, 0]
  const n = w * h
  for (let i = 0; i < pixels.length; i += 4) {
    channels[0] += pixels[i]
    channels[1] += pixels[i + 1]
    channels[2] += pixels[i + 2]
  }
  // Normalize both paths to 0..255 channel averages.
  const scale = isFloat ? 255 : 1
  return channels.map((c) => (c / n) * scale)
}

