    if (res.status() >= 400 && !res.url().includes('favicon')) {
      badResponses.push(`${res.status()} ${res.url()}`)
    }
  })

  await page.goto(URL, { waitUntil: 'networkidle0' })
  await sleep(2500)

  const initial = await page.evaluate(() => ({
    radius: blurRenderer.radius,
    sigma: blurRenderer.sigma,
    format: blurRenderer.getIntermediateFormatName(),
    taps: blurRenderer.kernel.offsets.length,
    webgl2: window._renderer ? true : drawingContext instanceof WebGL2RenderingContext,
    sliders: document.querySelectorAll('input[type=range]').length,
    canvasW: document.querySelector('canvas').width,
    canvasH: document.querySelector('canvas').height,
  }))
  console.log('initial state:', JSON.stringify(initial, null, 2))

  // Pixel stats helper: mean and spread of the rendered canvas
  const pixelStats = () =>
    page.evaluate(() => {
      const c = document.querySelector('canvas')
      const gl = c.getContext('webgl2') || c.getContext('webgl')
      const w = c.width
      const h = c.height
      const pixels = new Uint8Array(w * h * 4)
      gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, pixels)
      let sum = 0
      let sumSq = 0
      let bright = 0
      const n = w * h
      for (let i = 0; i < pixels.length; i += 4) {
        const lum = (pixels[i] + pixels[i + 1] + pixels[i + 2]) / 3
        sum += lum
        sumSq += lum * lum
        if (lum > 60) bright++
      }
      const mean = sum / n
      const variance = sumSq / n - mean * mean
      return { mean, stdDev: Math.sqrt(Math.max(variance, 0)), brightRatio: bright / n }
    })

  const statsDefault = await pixelStats()
  console.log('default (radius=10) pixel stats:', JSON.stringify(statsDefault))
  await page.screenshot({ path: 'smoke-default.png' })

  // Zero-radius passthrough
  await page.evaluate(() => {
    const sliders = document.querySelectorAll('input[type=range]')
    sliders[0].value = '0'
  })
  await sleep(1500)
  const zero = await page.evaluate(() => ({
    radius: blurRenderer.radius,
    taps: blurRenderer.kernel.offsets.length,
    weights: Array.from(blurRenderer.kernel.weights),
  }))
  console.log('radius=0 state:', JSON.stringify(zero))
  const statsZero = await pixelStats()
  console.log('radius=0 pixel stats:', JSON.stringify(statsZero))
  await page.screenshot({ path: 'smoke-radius0.png' })

  // Max radius: check it runs and measure frame rate
  await page.evaluate(() => {
    const sliders = document.querySelectorAll('input[type=range]')
    sliders[0].value = '64'
    sliders[1].value = '12'
  })
  await sleep(3000)
  const maxed = await page.evaluate(() => ({
    radius: blurRenderer.radius,
    sigma: blurRenderer.sigma,
    taps: blurRenderer.kernel.offsets.length,
    fps: frameRate(),
    status: document.querySelector('.status').textContent,
  }))
  console.log('radius=64 state:', JSON.stringify(maxed, null, 2))
  const statsMax = await pixelStats()
  console.log('radius=64 pixel stats:', JSON.stringify(statsMax))
  await page.screenshot({ path: 'smoke-radius64.png' })

  // Invalid sigma handling through the slider's 0 position
  await page.evaluate(() => {
    const sliders = document.querySelectorAll('input[type=range]')
    sliders[0].value = '20'
    sliders[1].value = '0'
  })
  await sleep(1000)
  const sigmaFallback = await page.evaluate(() => ({
    sigma: blurRenderer.sigma,
    taps: blurRenderer.kernel.offsets.length,
  }))
  console.log('sigma=0 fallback state:', JSON.stringify(sigmaFallback))

  // Over-cap input: simulate setter directly
  const capped = await page.evaluate(() => {
    blurRenderer.setRadius(999)
    return { radius: blurRenderer.radius, taps: blurRenderer.kernel.offsets.length }
  })
  console.log('over-cap setter state:', JSON.stringify(capped))
  await sleep(500)

  // Fallback path: hide float extensions from the constructor to force the
  // UNSIGNED_BYTE path, then render the same static scene through both
  // renderers and compare outputs to check for color drift.
  const fallback = await page.evaluate(async () => {
    const nextFrame = () =>
      new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)))
    const staticScene = () => {
      clear()
      push()
      background(10)
      noStroke()
      lights()
      push()
      emissiveMaterial(255, 40, 40)
      translate(-60, 0, 0)
      sphere(35)
      pop()
      push()
      emissiveMaterial(40, 120, 255)
      translate(60, 0, 0)
      sphere(35)
      pop()
      push()
      fill(60)
      translate(0, 150, 0)
      rotateX(PI / 2)
      plane(900, 900)
      pop()
      pop()
    }
    const readFbo = (fbo, isFloat) => {
      const gl = drawingContext
      const w = fbo.width * fbo.density
      const h = fbo.height * fbo.density
      // A float color attachment can only be read back as FLOAT; reading a
      // byte attachment with FLOAT is equally invalid, so match the type.
      const pixels = isFloat
        ? new Float32Array(w * h * 4)
        : new Uint8Array(w * h * 4)
      gl.bindFramebuffer(gl.FRAMEBUFFER, fbo.framebuffer)
      gl.readPixels(0, 0, w, h, gl.RGBA, gl.FLOAT, pixels)
      gl.bindFramebuffer(gl.FRAMEBUFFER, null)
      const channels = [0, 0, 0]
      const n = w * h
      for (let i = 0; i < pixels.length; i += 4) {
        channels[0] += pixels[i]
        channels[1] += pixels[i + 1]
        channels[2] += pixels[i + 2]
      }
      // Normalize both paths to 0..255 channel averages.
      const scale = isFloat ? 255 : 1
      return channels.map((c) => (c / n) * scale)
    }

    blurRenderer.setRadius(20)
    blurRenderer.setSigma(6)
    for (let i = 0; i < 5; i++) {
      blurRenderer.draw(staticScene)
      await nextFrame()
    }
    const floatFormat = blurRenderer.getIntermediateFormatName()
    const floatMeans = readFbo(blurRenderer.fboB, floatFormat === 'FLOAT')

    const gl = drawingContext
    const origGetExtension = gl.getExtension.bind(gl)
    gl.getExtension = (name) =>
      name === 'EXT_color_buffer_float' || name === 'EXT_float_blend'
        ? null
        : origGetExtension(name)
    const byteRenderer = createGaussianBlurRenderer({ radius: 20, sigma: 6 })
    gl.getExtension = origGetExtension
    const byteFormat = byteRenderer.getIntermediateFormatName()
    for (let i = 0; i < 5; i++) {
      byteRenderer.draw(staticScene)
      await nextFrame()
    }
    const byteMeans = readFbo(byteRenderer.fboB, false)
    const channelDiffs = floatMeans.map((v, i) => Math.abs(v - byteMeans[i]))
    return { floatFormat, byteFormat, floatMeans, byteMeans, channelDiffs }
  })
  console.log('fallback comparison:', JSON.stringify(fallback, null, 2))
  await page.screenshot({ path: 'smoke-byte-fallback.png' })

  const failures = []
  const expect = (name, cond, detail) => {
    console.log((cond ? 'PASS ' : 'FAIL ') + name + (detail ? ` (${detail})` : ''))
    if (!cond) failures.push(name)
  }

  expect('renderer initialized', initial.radius === 10)
  expect('float intermediate path active', initial.format === 'FLOAT', initial.format)
  expect('two sliders present', initial.sliders === 2)
  expect('default kernel length 21', initial.taps === 21, String(initial.taps))
  expect('canvas is not blank (default)', statsDefault.brightRatio > 0.001, String(statsDefault.brightRatio))
  expect('radius=0 identity kernel', zero.taps === 1 && zero.weights[0] === 1)
  expect('radius=0 renders content', statsZero.brightRatio > 0.001, String(statsZero.brightRatio))
  expect(
    'blur softens edges: stdDev drops at radius 64',
    statsMax.stdDev < statsZero.stdDev,
    `zero=${statsZero.stdDev.toFixed(2)} max=${statsMax.stdDev.toFixed(2)}`,
  )
  expect('max radius capped at 64', maxed.radius === 64 && maxed.taps === 129)
  expect('animation still running at radius 64 (>10 fps)', maxed.fps > 10, `${maxed.fps.toFixed(1)} fps`)
  expect('sigma=0 falls back to finite positive value', sigmaFallback.sigma > 0 && Number.isFinite(sigmaFallback.sigma))
  expect('setRadius(999) capped', capped.radius === 64 && capped.taps === 129)
  expect('forced fallback reports UNSIGNED_BYTE', fallback.byteFormat === 'UNSIGNED_BYTE', fallback.byteFormat)
  expect('reference renderer stayed FLOAT', fallback.floatFormat === 'FLOAT', fallback.floatFormat)
  expect(
    'byte fallback stays close to float per channel (<2/255 mean diff)',
    fallback.channelDiffs.every((d) => d < 2),
    JSON.stringify(fallback.channelDiffs),
  )
  expect('no page errors', pageErrors.length === 0, pageErrors.join(' | '))
  const badConsole = consoleMessages.filter(
    (m) => m.startsWith('[error]') && !m.includes('Failed to load resource'),
  )
  expect('no console errors', badConsole.length === 0, badConsole.join(' | '))
  expect('no failed resource loads', badResponses.length === 0, badResponses.join(' | '))

  console.log('\nall console messages:')
  for (const m of consoleMessages) console.log('  ' + m)

  await browser.close()
  console.log(failures.length === 0 ? '\nSMOKE PASSED' : `\nSMOKE FAILED: ${failures.join(', ')}`)
  process.exit(failures.length === 0 ? 0 : 1)
})().catch((err) => {
  console.error(err)
  process.exit(1)
})

