    if (!cond) failures.push(name)
  }
  expect('constructor options applied', state.radius === 15 && state.taps === 31)
  expect('sigma option applied', Math.abs(state.sigma - 5) < 1e-9, String(state.sigma))
  expect('float intermediates', state.format === 'FLOAT', state.format)
  expect('no page errors', pageErrors.length === 0, pageErrors.join(' | '))
  expect('no failed resource loads', badResponses.length === 0, badResponses.join(' | '))

  await browser.close()
  console.log(failures.length === 0 ? '\nEXAMPLE SMOKE PASSED' : `\nFAILED: ${failures.join(', ')}`)
  process.exit(failures.length === 0 ? 0 : 1)
})().catch((err) => {
  console.error(err)
  process.exit(1)
})
